function groupSettings(){const account=store();const n=sheet('分组管理',`<div class="km-menu-actions">${account.groups.map(g=>btn('edit-group',`${E(g.name)} · ${g.members.length}人`,g.id)).join('')}${btn('edit-group','新建分组')}</div>`);}
function editGroup(id){const account=store(),old=account.groups.find(g=>g.id===id);const n=sheet('编辑分组',`<form class="km-form"><label>分组名称<input name="name" value="${E(old?.name||'')}" maxlength="40" required></label>${selectPeople(old?.members)}<button class="km-primary">保存</button>${old?btn('delete-group','删除分组',id,'km-danger'):''}</form>`);$('form',n).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,g={id:old?.id||uid(),name:f.elements.name.value.trim(),members:[...f.querySelectorAll('[name=ids]:checked')].map(x=>x.value)};if(!g.name)return;const before=account.groups.slice();account.groups=old?account.groups.map(x=>x.id===old.id?g:x):[...account.groups,g];try{await persist();groupSettings();}catch{account.groups=before;showToast('保存失败');}};}
function privacySettings(){const a=store(),n=sheet('朋友圈权限',`<form class="km-form"><fieldset><legend>不看谁的朋友圈</legend>${selectPeople(a.hidden,'hidden')}</fieldset><fieldset><legend>不让谁看我的朋友圈</legend>${selectPeople(a.blocked,'blocked')}</fieldset><button class="km-primary">保存</button></form>`);$('form',n).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,old={hidden:a.hidden,blocked:a.blocked};a.hidden=[...f.querySelectorAll('[name=hidden]:checked')].map(x=>x.value);a.blocked=[...f.querySelectorAll('[name=blocked]:checked')].map(x=>x.value);try{await persist();close();}catch{Object.assign(a,old);showToast('保存失败');}};}
async function generate(owner,button,automatic=false){const c=character(owner);if(!c||postJobs.has(String(c.id)))return;postJobs.add(String(c.id));try{const account=personaKey(),epoch=c.momentsSettings?.epoch||0,s=settings(owner);let songs=[];if(s.musicSharing){try{songs=(await songsFor(owner)).slice(0,30);}catch(error){showToast('歌曲列表暂不可用，本次只生成动态');}}const additions=await generatePeekMoments(button,c.id,{songs,automatic,maxCount:automatic?1:3});if(!additions)return;for(const p of additions)p.source='generated';if(account!==personaKey()||(c.momentsSettings?.epoch||0)!==epoch)return;
 if(s.imageGeneration)for(const p of additions)if(p.imageDescription&&c.moments.includes(p))await generateImage({p,c,owner,key:owner+'/'+p.id}).catch(e=>showToast('动态已保存，配图未完成：'+e.message));await persist();}finally{postJobs.delete(String(c.id));}}

async function generateDueRoles(candidates){
 const targets=candidates.filter(c=>chars().includes(c)&&c.momentsSettings?.automatic&&!postJobs.has(String(c.id))&&(!window.KissClock||window.KissClock.canPost(c))&&(!window.KissMomentsPolicy||window.KissMomentsPolicy.canAuto(c)));
 if(!targets.length)return;if(targets.length===1)return generate(String(targets[0].id),null,true);
 const account=personaKey(),prior=new Map(targets.map(c=>[c,c.moments])),epochs=new Map(targets.map(c=>[c,c.momentsSettings?.epoch||0]));targets.forEach(c=>postJobs.add(String(c.id)));
 try{
  let rooms=[];if(targets.some(c=>c.momentsSettings?.musicSharing)&&window.KissHearUData)try{rooms=await window.KissHearUData.snapshot();}catch{}
  const songs=new Map();for(const c of targets){let list=[];if(c.momentsSettings?.musicSharing)try{list=(await songsFor(c.id,rooms)).slice(0,8);}catch{}songs.set(c,list);}
  const budget=Math.max(600,Math.min(6000,Math.floor(50000/targets.length)));
  const roles=targets.map(c=>({...liteRole(c,budget),existing:(c.moments||[]).slice(0,20).map(p=>({id:p.id,content:String(p.content||'').slice(0,180),pinned:!!p.pinned})),songs:songs.get(c).map((s,index)=>({index,title:s.title,artist:s.artist}))}));
  const config=resolveAuxiliaryApiConfig('peekMoments');if(!config.url||!config.key||!config.model)throw Error('请先配置动态使用的 API');
  const instruction='为每个给定角色各生成1条全新的朋友圈。逐一遵守该角色人设、规则、原本语言、生活背景及当地时间，各角色独立，不知道其他角色也在发布，不提起其他角色或互动。不重复各自existing；不把私密对话改成公开动态，不编造用户行为。外语/粤语正文以及bilingual为true时必须同次提供普通话译文，不得为了省译文改用普通话。可给imageDescription；不要编造图片URL。你可自行决定这条动态是否值得置顶，pinned为true时置顶，否则false；不为凑数置顶。可在本角色项中给pinIds数组整理自己的置顶，最多3项，只能用本角色existing的id或new（本次新帖）；空数组清空，省略保留旧置顶。可从该角色自己的songs里选择一首并给musicIndex，否则null。只返回JSON {"posts":[{"roleId":"给定ID","content":"角色原文","translation":"普通话译文，普通话正文留空","needsTranslation":false,"pinned":false,"pinIds":["new"],"imageDescription":"可空","musicIndex":null}]}。每个角色最多一项，文字不超过300字。不评论其他角色，不输出私聊。';
  const {requestBody,headers,endpoint}=buildChatApiRequest(config,[{role:'system',content:instruction},{role:'user',content:JSON.stringify({roles})}],{temperature:config.temperatureEnabled===false?undefined:config.temperature??.85});
  const raw=await fetchAiResponse(config,requestBody,headers,endpoint);let out;try{out=JSON.parse(String(raw).replace(/<thinking>[\s\S]*?<\/thinking>/gi,'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));}catch{throw Error('自动动态批量格式不正确，没有追加调用');}
  if(!Array.isArray(out.posts))throw Error('模型没有返回自动动态，没有追加调用');const rows=new Map();for(const row of out.posts){if(!row||row.roleId==null)continue;const id=String(row.roleId);if(rows.has(id))throw Error('自动动态含重复角色，未写入');rows.set(id,row);}
  if(account!==personaKey())return;const added=[];
  for(const c of targets){if(!chars().includes(c)||!c.momentsSettings?.automatic||c.moments!==prior.get(c)||(c.momentsSettings?.epoch||0)!==epochs.get(c)||window.KissClock&&!window.KissClock.canPost(c)||window.KissMomentsPolicy&&!window.KissMomentsPolicy.canAuto(c))continue;const row=rows.get(String(c.id));if(!row||typeof row.content!=='string'||!row.content.trim())continue;
   let text;try{text=window.KissMomentsLanguage?.complete(row.content,row.translation,row.needsTranslation===true||c.bilingualModeEnabled===true)||{content:row.content.trim(),translation:String(row.translation||'')};}catch{continue;}
   if(namesAnotherRole(text.content,c)||namesAnotherRole(text.translation,c))continue;const key=s=>String(s).replace(/\s+/g,'').toLowerCase();if((c.moments||[]).some(p=>key(p.content)===key(text.content)))continue;
   const list=songs.get(c),p={id:'moment_'+uid(),author:pname(c),content:text.content.slice(0,600),translation:text.translation.slice(0,3000),imageDescription:typeof row.imageDescription==='string'?row.imageDescription.trim().slice(0,600):'',music:Number.isInteger(row.musicIndex)&&row.musicIndex>=0&&list[row.musicIndex]?structuredClone(list[row.musicIndex]):null,timestamp:Date.now(),likes:[],comments:[],plainText:true,source:'generated'};
   window.KissMomentsPolicy?.pin(c,p,row.pinned);p.device=window.KissMomentsPolicy?.device(c)||'';const rollbackPins=window.KissMomentsPolicy?.arrangePins(c,[p],row.pinIds);c.moments=[p,...(c.moments||[])];added.push({c,p,rollbackPins});window.KissMomentsPolicy?.audit('自动动态已生成',{role:pname(c),postId:p.id,translation:!!p.translation,music:!!p.music,quota:window.KissMomentsPolicy.period(c)});
  }
  try{if(added.length)await persist();}catch(error){for(const {c,p,rollbackPins}of added){c.moments=(c.moments||[]).filter(m=>m!==p);rollbackPins?.();}throw error;}
  for(const {c,p}of added)if(c.momentsSettings?.imageGeneration&&p.imageDescription)await generateImage({c,p,owner:String(c.id),key:String(c.id)+'/'+p.id}).catch(error=>console.warn('[Moments image]',error.message));
 }finally{targets.forEach(c=>postJobs.delete(String(c.id)));}
}

async function generateImage(r){const c=r.c,account=personaKey(),epoch=c?.momentsSettings?.epoch||0;if(!r.p.imageDescription)throw Error('这条动态没有配图描述');if(!window.executeImageGeneration)throw Error('绘图工坊尚未就绪');const {imageData}=await window.executeImageGeneration(structuredClone(db.workshopSettings||{}),r.p.imageDescription);if(account!==personaKey()||!ref(r.key)||ref(r.key).p!==r.p||(c?.momentsSettings?.epoch||0)!==epoch)return;const image=/^(https?:|data:image)/.test(imageData)?imageData:'data:image/png;base64,'+imageData;const before=r.p.images;r.p.images=[image];try{await persist();}catch(e){r.p.images=before;throw e;}}
function inWindow(now,start,end){const mins=v=>{const [h,m]=String(v).split(':').map(Number);return h*60+m;},n=now.getHours()*60+now.getMinutes(),a=mins(start),b=mins(end);return a===b?true:a<b?n>=a&&n<=b:n>=a||n<=b;}
async function tick(){if(scheduleBusy||document.hidden||typeof db==='undefined'||window.kissCleanupLocked)return;scheduleBusy=true;try{const now=Date.now();const due=chars().filter(c=>{const s=c.momentsSettings;if(!s?.automatic||postJobs.has(String(c.id)))return false;if(window.KissMomentsPolicy&&!window.KissMomentsPolicy.canAuto(c))return false;if(window.KissClock?!window.KissClock.canPost(c):!inWindow(new Date(),s.start||'09:00',s.end||'22:00'))return false;const period=window.KissMomentsPolicy?.period(c);return period&&s.lastAttemptPeriodKey!==period.key||now-(s.lastAttempt||s.lastAuto||0)>=Math.max(15,Number(s.interval)||180)*60000;});if(!due.length)return;window.KissMomentsPolicy?.audit('自动发布调度命中',due.map(c=>({role:pname(c),quota:window.KissMomentsPolicy.period(c)})));for(const c of due){c.momentsSettings.lastAttempt=now;c.momentsSettings.lastAttemptPeriodKey=window.KissMomentsPolicy?.period(c)?.key||'';}await saveData();await generateDueRoles(due);for(const c of due)if(chars().includes(c)&&c.momentsSettings)c.momentsSettings.lastAuto=Date.now();await saveData();}catch(error){console.warn('[Moments schedule]',error.message);}finally{scheduleBusy=false;}}

