 if(a==='audience')return editAudience(key);
 if(a==='delete-post'){const r=ref(key);if(!r||!confirm('删除这条动态及其点赞、评论？'))return;const owner=r.c||store(),field=r.c?'moments':'posts',old=owner[field];owner[field]=old.filter(p=>p!==r.p);try{await saveData();close();if(view.page==='detail')show(stack.pop()||{page:'feed',owner:SELF},false);else changed();}catch(err){owner[field]=old;throw err;}return;}
 if(a==='comment'||a==='reply'){const [postKey,cid]=key.split('|'),r=ref(postKey);if(!r)return;const parent=r.p.comments.find(c=>c.id===cid);const n=sheet(parent?'回复 '+parent.author:'发表评论',`<form class="km-form"><textarea name="content" maxlength="2000" rows="3" required placeholder="写下评论…"></textarea><button class="km-primary">发送</button></form>`);$('form',n).onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,send=$('button',f);send.disabled=true;try{await addComment(postKey,f.elements.content.value,cid);close();}catch(err){showToast(err.message);}finally{send.disabled=false;}};return;}
